CREATE OR REPLACE FUNCTION public.load_units(p_window_ids uuid[], p_project_id uuid, p_actor text DEFAULT NULL::text)
 RETURNS SETOF windows
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_id uuid;
  v_from uuid;
  v_window windows;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a foreman-level user or above can load units for a run';
  end if;

  foreach v_id in array coalesce(p_window_ids, array[]::uuid[])
  loop
    -- Only load a unit that belongs to this job and is warehouse-ready.
    select location_id into v_from
    from windows
    where id = v_id
      and project_id = p_project_id
      and status in ('in_warehouse', 'staged');
    if not found then
      continue;
    end if;

    update windows
    set status = 'loaded', location_id = null
    where id = v_id
    returning * into v_window;

    insert into movements (window_id, event, from_location_id, project_id, actor)
    values (v_id, 'loaded', v_from, p_project_id, coalesce(p_actor, auth.uid()::text));

    return next v_window;
  end loop;

  return;
end;
$function$

CREATE OR REPLACE FUNCTION public.load_window(p_window_id uuid, p_actor text DEFAULT NULL::text)
 RETURNS windows
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_window windows;
  v_from uuid;
  v_status text;
begin
  select location_id, status into v_from, v_status from windows where id = p_window_id;
  if v_status is null then
    raise exception 'unknown window %', p_window_id;
  end if;
  if v_status not in ('in_warehouse', 'staged') then
    raise exception 'unit is not warehouse-ready to load (status %)', v_status;
  end if;

  update windows
  set status = 'loaded', location_id = null
  where id = p_window_id
  returning * into v_window;

  insert into movements (window_id, event, from_location_id, project_id, actor)
  values (p_window_id, 'loaded', v_from, v_window.project_id, p_actor);

  return v_window;
end;
$function$

CREATE OR REPLACE FUNCTION public.lock_serial()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if OLD.serial is not null and NEW.serial is distinct from OLD.serial then
    NEW.serial := OLD.serial;
  end if;
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.move_window(p_window_id uuid, p_location_id uuid, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS windows
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_window windows;
  v_zone text;
  v_from uuid;
  v_status text;
  v_event text;
begin
  select zone into v_zone from locations where id = p_location_id;
  if v_zone is null then
    raise exception 'unknown location %', p_location_id;
  end if;

  select location_id into v_from from windows where id = p_window_id;

  v_status := case v_zone
    when 'J' then 'staged'
    when 'D' then 'damaged'
    else 'in_warehouse'
  end;
  v_event := case
    when v_from is null then 'putaway'
    when v_zone = 'J' then 'staged'
    when v_zone = 'D' then 'damaged'
    else 'moved'
  end;

  update windows
  set location_id = p_location_id, status = v_status
  where id = p_window_id
  returning * into v_window;

  insert into movements (window_id, event, from_location_id, to_location_id, actor, reason)
  values (p_window_id, v_event, v_from, p_location_id, p_actor, p_reason);

  return v_window;
end;
$function$

